// ============================================================
//  MOONKAI — KAEL, SERAPH and SION in pixel art (Pixel Studio style).
//  Built on js/pixel_fighter.js: same rigs, moves, weapons and form changes as
//  their vector versions, painted as outlined cel-shaded pixels with smooth
//  pose blending and kick trails. Portraits are Pixel Studio busts.
// ============================================================

const pxR = (x, k = 4) => Math.round(x * k) / k;

// ---------------- KAEL, the Hollow Core ----------------
const KAELPX = PixelArt.make({
  id: 'kael', win: [-125, -190, 270, 230], trail: 'rgba(63,224,255,',
  state(v, t) { return { D: !!v.transformed, broken: !!v.coreBroken, tail: pxR(Math.sin(t * 4)), wing: pxR(Math.sin(t * 3)), core: pxR(.8 + .2 * Math.sin(t * 6)) }; },
  body(g, P, s) {
    const D = s.D, { L } = g;
    const S = D ? { skin: ['#6e1414', '#4a0c0c'], skinFar: ['#4a0c0c', '#2a0606'], top: ['#3a0b0b', '#220606'], topFar: ['#220606', '#140303'], pants: ['#2a0808', '#180404'], pantsFar: ['#180404', '#0a0202'],
      boots: ['#0a0202', '#050101'], bootsFar: ['#050101', '#050101'], belt: ['#ff3b1a', '#aa2a10'], glove: ['#1a0303', '#0a0101'], gloveFar: ['#0a0101', '#050101'], bareArms: true }
      : { skin: ['#c9b3a0', '#a89080'], skinFar: ['#a89080', '#8a7262'], top: ['#2b3440', '#1b222b'], topFar: ['#1b222b', '#12171d'], pants: ['#232a33', '#161b21'], pantsFar: ['#161b21', '#0e1115'],
      boots: ['#0e1115', '#070a0e'], bootsFar: ['#070a0e', '#070a0e'], belt: ['#3fe0ff', '#1d8aa0'], glove: ['#2b3440', '#1b222b'], gloveFar: ['#1b222b', '#12171d'] };
    let core;
    g.humanoid(P, S, {
      back(P) {
        if (!D) return;
        for (const side of [-1, 1]) {
          const m = new DOMMatrix().translate(P.sh[0] - 4, P.sh[1] + 2).rotate((side * .15 - .35 + s.wing * .08) * 180 / Math.PI);
          g.paint([g.moved(g.poly([[0, 0], [-30, -44 * (side < 0 ? 1.1 : 1)], [-70, -30], [-58, -8], [-74, 4], [-46, 10], [-50, 26], [-16, 16]]), m)], side < 0 ? '#1a0303' : '#2a0606', side < 0 ? '#0a0101' : '#1a0303');
        }
        const a = [P.hip[0] - 6, P.hip[1] + 4], c = [P.hip[0] - 40, P.hip[1] + 30], e = [P.hip[0] - 46 + s.tail * 6, P.hip[1] - 4], pts = [];
        for (let i = 0; i <= 6; i++) { const u = i / 6; pts.push([(1 - u) ** 2 * a[0] + 2 * u * (1 - u) * c[0] + u * u * e[0], (1 - u) ** 2 * a[1] + 2 * u * (1 - u) * c[1] + u * u * e[1]]); }
        g.paint(pts.slice(1).map((q, i) => g.cap(pts[i], q, 2.4)), '#2a0606', '#1a0303');
        g.paint([g.poly([[e[0] - 5, e[1]], [e[0], e[1] - 10], [e[0] + 5, e[1]]])], '#ff3b1a', '#aa2a10');
      },
      chest(P) {
        const [x, y] = L(P.hip, P.sh, .72);
        if (!D && !s.broken) g.paint([g.cap([x - 10, y - 8], [x + 10, y + 8], 1.8), g.cap([x + 10, y - 8], [x - 10, y + 8], 1.8)], '#555566', '#3a3a48');
        g.paint([g.ell(x, y, 7, 7)], '#0e1115', '#070a0e');
        const hot = D || s.broken;
        g.fill(g.ell(x, y, 4.4 * s.core, 4.4 * s.core), hot ? '#ff5a1a' : '#3fe0ff');
        g.fill(g.ell(x, y, 2, 2), hot ? '#fff2a0' : '#ffffff');
        core = [x, y];
      },
      head(P) {
        const [hx, hy] = P.head;
        if (!D) {
          g.paint([g.poly([[hx - 12, hy - 2], [hx - 14, hy - 12], [hx - 4, hy - 13], [hx + 2, hy - 16], [hx + 12, hy - 8], [hx + 4, hy - 6]])], '#e8e8f0', '#b8b8c8');
          g.fill(g.ell(hx + 6, hy, 2, 1.8), '#3fe0ff');
          g.line([[hx + 2, hy - 3], [hx + 9, hy - 3]], '#8a8a98', 1.2);
          g.line([[hx + 3, hy - 5], [hx + 7, hy + 3]], '#8a4a4a', 1.2);
          g.line([[hx + 5, hy + 6], [hx + 10, hy + 6]], '#7a5a50', 1.2);
        } else {
          g.paint([g.shape([['M', hx - 6, hy - 8], ['Q', hx - 20, hy - 20, hx - 14, hy - 34], ['Q', hx - 10, hy - 18, hx - 1, hy - 10]])], '#140202', '#050101');
          g.paint([g.shape([['M', hx + 4, hy - 9], ['Q', hx + 8, hy - 24, hx + 20, hy - 30], ['Q', hx + 12, hy - 18, hx + 10, hy - 6]])], '#140202', '#050101');
          g.fill(g.ell(hx + 6, hy, 2.4, 2.2), '#fff2a0');
          g.line([[hx + 2, hy + 6], [hx + 11, hy + 6]], '#ff5a1a', 2);
        }
      },
    });
    return { core };
  },
  pre(c, v, P, s) { if (s.D) glowCircle(c, 0, -60, 95, 'rgba(255,40,10,0.3)', 'rgba(120,0,0,0)'); },
  post(c, v, P, s, info) {
    const hot = s.D || s.broken;
    c.globalCompositeOperation = 'lighter';
    glowCircle(c, P.head[0] + 6, P.head[1], s.D ? 9 : 5, s.D ? 'rgba(255,90,20,1)' : 'rgba(63,224,255,0.8)', 'rgba(0,0,0,0)');
    if (info.core) glowCircle(c, info.core[0], info.core[1], 14 * s.core, hot ? 'rgba(255,90,26,0.7)' : 'rgba(63,224,255,0.6)', 'rgba(0,0,0,0)');
    c.globalCompositeOperation = 'source-over';
  },
});

// ---------------- SERAPH, the Last Light ----------------
const SERPX = PixelArt.make({
  id: 'seraph', win: [-180, -265, 405, 305], B: .98, trail: 'rgba(255,240,190,',
  state(v, t, st) {
    const A = !!v.transformed;
    return { A, hair: pxR(Math.sin(t * 3)), wing: pxR(Math.sin(t * (A ? 3.5 : 2))), rib: pxR(Math.sin(t * 6), 2), ang: pxR(SERPX.ease(st, 'ang', aurSwingAng(v) + .2), 40) };
  },
  body(g, P, s) {
    const A = s.A, { L } = g;
    const fan = (m, len, spread, cols) => {
      const pieces = [];
      for (let i = 0; i < 5; i++) { const a = -2.75 + i * .3 * (spread + .7), l = len * (1 - i * .09), d = [Math.cos(a), Math.sin(a)];
        pieces.push(g.moved(g.ell(d[0] * l / 2, d[1] * l / 2, l / 2, 7, a), m)); }
      g.paint(pieces, cols[0], cols[1]);
    };
    g.humanoid(P, {
      limb: .9, bulk: .9, hips: 1.25, skin: ['#f0d0b0', '#d8b090'], skinFar: ['#d8b090', '#b89070'],
      top: A ? ['#fffdf6', '#d8d0f0'] : ['#f4f0ff', '#c8c0e8'], topFar: ['#c8c0e8', '#a898c8'], pants: ['#e8e0ff', '#bab0d8'], pantsFar: ['#bab0d8', '#9a90b8'],
      skirt: A ? ['#ffffff', '#e0dcf0'] : ['#fffbe8', '#e6dcc0'], boots: ['#e6c060', '#b8903a'], bootsFar: ['#b8903a', '#8a6a2a'],
      belt: A ? ['#fff0b0', '#e6c060'] : ['#e6c060', '#b8903a'], bracers: A ? ['#fff0b0', '#e6c060'] : ['#e6c060', '#b8903a'],
    }, {
      back(P) {
        if (A) for (const [i, rot, sc] of [[2, -.55, .75], [1, .35, .9], [0, -.1, 1.1]])
          fan(new DOMMatrix().translate(P.sh[0] - 6, P.sh[1] + 2 + i * 6).rotate((rot + s.wing * .06 * (i + 1)) * 180 / Math.PI), 84 * sc, 1, i ? ['#d8d0ff', '#a898e0'] : ['#f4f0ff', '#c0b4ee']);
        else for (const side of [-1, 1]) fan(new DOMMatrix().translate(P.sh[0] - 6, P.sh[1] + 2).rotate((side * .14 + s.wing * .05 * side) * 180 / Math.PI), 72, .3, side < 0 ? ['#dcd6ee', '#b8b0d8'] : ['#f6f2ff', '#c8c0e8']);
        const [hx, hy] = P.head;
        g.paint([g.shape([['M', hx - 9, hy - 10], ['Q', hx - 24, hy + 8, hx - 20 + s.hair * 3, hy + 44], ['L', hx - 8, hy + 36], ['Q', hx - 4, hy + 12, hx + 2, hy - 2]])], '#ffe9a0', '#e6c060');
      },
      chest(P) {
        const [x, y] = L(P.hip, P.sh, .66);
        g.paint([g.poly([[x, y - 7], [x + 3, y], [x, y + 7], [x - 3, y]]), g.cap([x - 6, y], [x + 6, y], 1.1)], '#e6c060', '#b8903a', false);
      },
      head(P) {
        const [hx, hy] = P.head;
        g.paint([g.shape([['M', hx - 11, hy - 2], ['Q', hx - 6, hy - 16, hx + 9, hy - 12], ['Q', hx + 13, hy - 6, hx + 9, hy - 2], ['L', hx + 1, hy - 7]])], '#ffe9a0', '#e6c060');
        g.fill(g.ell(hx + 6.5, hy - 1.4, 3.2, 1.8), '#5a8ad8');
        g.fill(g.ell(hx + 6, hy - 2, 1, 1), '#ffffff');
        g.line([[hx + 2, hy - 4.5], [hx + 9.5, hy - 5]], '#2a1a22', 1.3);
        g.line([[hx + 10, hy - 2], [hx + 12, hy + 2], [hx + 10.5, hy + 3]], '#c89878', 1);
        g.line([[hx + 6.5, hy + 6.5], [hx + 9.5, hy + 6.3]], '#b87878', 1.2);
        g.fill(g.ell(hx + 3, hy + 3, 1.6, 1), '#ffb6b9');
      },
      front(P) {
        const len = A ? 150 : 132, m = new DOMMatrix().translate(P.fH[0], P.fH[1]).rotate(s.ang * 180 / Math.PI);
        const pt = (x, y) => { const q = m.transformPoint(new DOMPoint(x, y)); return [q.x, q.y]; };
        g.paint([g.moved(g.cap([-len * .35, 0], [len * .78, 0], 1.9), m)], '#b8903a', '#8a6a2a');
        g.paint([g.moved(g.shape([['M', len * .76, -6], ['Q', len * .9, -7, len, 0], ['Q', len * .9, 7, len * .76, 6]]), m)], '#fff6d8', '#e6dcc0');
        g.paint([g.moved(g.poly([[len * .72, -10], [len * .78, 0], [len * .72, 10], [len * .75, 0]]), m)], '#e6c060', '#b8903a');
        g.line([pt(len * .7, 2), pt(len * .6, 14 + s.rib * 4), pt(len * .5, 18)], '#8a70c0', 2, true);
      },
    });
  },
  pre(c, v, P, s) { if (s.A) glowCircle(c, 0, -80, 130, 'rgba(230,220,255,0.3)', 'rgba(200,190,255,0)'); },
  post(c, v, P, s) {
    const t = v.anim || 0, A = s.A, [hx, hy] = P.head, n = v.gauge ?? (A ? 5 : 3);
    c.save(); c.globalCompositeOperation = 'lighter';
    glowCircle(c, hx + 6.5, hy - 1.5, 5, 'rgba(120,170,255,0.7)', 'rgba(0,0,0,0)');
    c.strokeStyle = A ? 'rgba(255,250,220,1)' : 'rgba(255,220,130,0.95)'; c.lineWidth = 2.5; c.beginPath(); c.ellipse(hx - 2, hy - 22, 13, 4, -0.15, 0, Math.PI * 2); c.stroke();
    if (A) for (let i = 0; i < 8; i++) { const a = i * Math.PI / 4 + t * 0.5; c.beginPath(); c.moveTo(hx - 2 + Math.cos(a) * 15, hy - 22 + Math.sin(a) * 4.6); c.lineTo(hx - 2 + Math.cos(a) * 22, hy - 22 + Math.sin(a) * 7); c.stroke(); }
    const len = A ? 150 : 132; c.translate(P.fH[0], P.fH[1]); c.rotate(s.ang);
    c.strokeStyle = `rgba(255,245,200,${0.5 * (A ? .8 : .3)})`; c.lineWidth = 10; c.beginPath(); c.moveTo(len * 0.7, 0); c.lineTo(len, 0); c.stroke();
    c.restore();
    for (let i = 0; i < n; i++) { const a = t * 2.2 + i * Math.PI * 2 / Math.max(1, n); drawFeather(c, Math.cos(a) * 46, -70 + Math.sin(a) * 26, a + Math.PI / 2, 1, '#f4f0ff'); }
  },
});

// ---------------- SION, the Undead Juggernaut ----------------
function sionAxeAng(v) {
  const m = v.move, charging = m && m.sionCharge && v.mf < m.s;
  if (charging) return lerp(-1.9, -2.9, Math.min(1, v.smashCharge || 0));
  if (m && m.sionCharge) return 0.9;
  return { heavy: 0.4, slam: 0.9, punch: -0.2, punch2: 0, kick: -1.6, uppercut: -1.2, dash: 0.1, air_heavy: 0.7, air_spike: 1.3, hurt: 2.2, hurt_air: 2.3, victory: -1.57, intro: 1.3, kneel: 1.3, cast: -0.6 }[v.pose] ?? -1.9;
}
const SIONPX = PixelArt.make({
  id: 'sion', win: [-125, -235, 335, 280], B: 1.18, trail: 'rgba(255,150,90,',
  state(v, t, st) {
    const m = v.move, charging = m && m.sionCharge && v.mf < m.s;
    return { Z: !!v.zombie, J: !!v.transformed, ang: pxR(SIONPX.ease(st, 'ang', sionAxeAng(v)), 40), charge: charging ? pxR(v.smashCharge || 0, 5) : 0, chain: pxR(Math.sin(t * 4)) };
  },
  body(g, P, s) {
    const Z = s.Z, { L } = g;
    let axeHead;
    g.humanoid(P, {
      limb: 1.55, bulk: 1.7, hips: 1.3, skin: Z ? ['#6a8a6a', '#4a6a4a'] : ['#8e9aa0', '#6a767c'], skinFar: Z ? ['#4a6a4a', '#34503a'] : ['#6a767c', '#4a5458'],
      top: ['#4a3226', '#2a1a12'], topFar: ['#2a1a12', '#1a0f0a'], pants: ['#3a2a20', '#221610'], pantsFar: ['#221610', '#140c08'],
      boots: ['#1a1410', '#0a0806'], bootsFar: ['#0a0806', '#0a0806'], belt: ['#6a4a2a', '#4a3218'], glove: ['#5a4a3a', '#3a2e24'], gloveFar: ['#3a2e24', '#241c16'],
      bracers: ['#6a5a4a', '#4a3e30'], kneepads: ['#6a5a4a', '#4a3e30'],
    }, {
      back(P) {
        const pts = [[P.sh[0] - 12, P.sh[1]], [P.sh[0] - 30, P.hip[1] + 30]];
        for (let i = 0; i < 4; i++) pts.push([P.sh[0] - 26 + i * 7, P.hip[1] + 20 + (i % 2) * 12]);
        pts.push([P.sh[0] + 4, P.sh[1] + 6]);
        g.paint([g.poly(pts)], '#2a1a14', '#1a0f0a');
        if (s.J) for (let i = 1; i < 8; i++) { const u = i / 8, a = P.hip, c = [P.hip[0] - 30, P.hip[1] + 30 + s.chain * 6], e = [P.hip[0] - 50, P.hip[1] + 10];
          g.paint([g.ell((1 - u) ** 2 * a[0] + 2 * u * (1 - u) * c[0] + u * u * e[0], (1 - u) ** 2 * a[1] + 2 * u * (1 - u) * c[1] + u * u * e[1], 2.4, 1.8)], '#6a6a70', '#4a4a50'); }
      },
      chest(P) {
        const [x, y] = L(P.hip, P.sh, .6);
        g.paint([g.poly([[x - 12, y - 14], [x + 12, y - 14], [x + 12, y + 2], [x - 12, y + 2]])], '#5a4a3a', '#3a2e24');
        g.line([[x - 9, y - 10], [x + 9, y - 10]], '#6a5a4a', 1.2);
        g.fill(g.ell(x + 2, y + 8, 5, 3), Z ? '#3aaa4a' : '#5a1a14');
      },
      head(P) {
        const [hx, hy] = P.head;
        g.paint([g.poly([[hx - 13, hy + 2], [hx - 12, hy - 12], [hx + 8, hy - 15], [hx + 13, hy - 4], [hx + 3, hy - 4], [hx - 2, hy + 2]])], '#4a4a50', '#2a2a30');
        g.paint([[-8, 14], [0, 18], [7, 12]].map(([x, h]) => g.poly([[hx + x - 3, hy - 13], [hx + x - 1, hy - 13 - h], [hx + x + 3, hy - 14]])), '#2a2a30', '#1a1a20');
        g.paint([g.poly([[hx + 2, hy + 3], [hx + 14, hy + 3], [hx + 14, hy + 9], [hx + 2, hy + 9]])], '#6a6a70', '#4a4a50');
        for (let i = 0; i < 3; i++) g.line([[hx + 4 + i * 4, hy + 3], [hx + 4 + i * 4, hy + 9]], '#2a2a2a', 1);
        g.fill(g.ell(hx + 8, hy - 2, 2.2, 2), Z ? '#caffd0' : '#ffd0a0');
      },
      front(P) {
        const m = new DOMMatrix().translate(P.fH[0], P.fH[1]).rotate(s.ang * 180 / Math.PI);
        const pt = (x, y) => { const q = m.transformPoint(new DOMPoint(x, y)); return [q.x, q.y]; };
        g.paint([g.moved(g.cap([-30, 0], [110, 0], 3.2), m)], '#3a2a1a', '#241a10');
        g.paint([g.moved(g.shape([['M', 80, -4], ['Q', 96, -40, 124, -46], ['Q', 116, -10, 128, 16], ['Q', 100, 18, 80, 6]]), m)], '#6a6a70', '#4a4a50');
        g.line([pt(124, -44), pt(114, -12), pt(126, 14)], '#a8a8b0', 2, true);
        for (let i = 0; i < 3; i++) g.fill(g.moved(g.ell(96 + i * 8, -12 + i * 6, 2.6, 2.6), m), '#8a3a1a');
        axeHead = pt(110, -14);
      },
    });
    return { axeHead };
  },
  pre(c, v, P, s) { if (s.Z) glowCircle(c, 0, -70, 130, 'rgba(90,255,120,0.18)', 'rgba(0,0,0,0)'); },
  post(c, v, P, s, info) {
    c.save(); c.globalCompositeOperation = 'lighter';
    glowCircle(c, P.head[0] + 8, P.head[1] - 2, s.J || s.Z ? 10 : 7, s.Z ? 'rgba(90,255,120,1)' : 'rgba(255,60,30,1)', 'rgba(0,0,0,0)');
    if (s.charge > 0 && info.axeHead) glowCircle(c, info.axeHead[0], info.axeHead[1], 30 + 40 * s.charge, `rgba(255,90,40,${0.3 + 0.5 * s.charge})`, 'rgba(0,0,0,0)');
    c.restore();
  },
});

// ---------------- RAZOR, the Red Berserker ----------------
const RZ_ANG = { heavy: 0.7, slam: 1.2, punch: -0.1, kick: -1.4, uppercut: -1.3, dash: 0.1, air_heavy: 0.8, air_spike: 1.4, hurt: 2.2, hurt_air: 2.3, victory: -1.57, intro: -0.9, block: -1.8, charge: -2.4 };
const RAZORPX = PixelArt.make({
  id: 'razor', win: [-120, -235, 330, 275], B: 1.04, trail: 'rgba(255,60,60,',
  state(v, t, st) {
    const m = v.move, spin = !!(m && m.rzTempest), R = !!v.transformed, F = !!v.frenzy;
    const ang = spin ? (st.ang = (t * 20) % (Math.PI * 2)) : RAZORPX.ease(st, 'ang', RZ_ANG[v.pose] ?? -2.2);
    return { R, F, spin, ang: pxR(ang, 40), s1: pxR(Math.sin(t * 6)), s2: pxR(Math.sin(t * 5)) };
  },
  body(g, P, s) {
    const R = s.R, rage = R || s.F, { L } = g;
    const skin = R ? ['#a05050', '#7a3434'] : ['#b08060', '#8a5a40'], skinFar = R ? ['#7a3434', '#5a2424'] : ['#8a5a40', '#6a4430'];
    g.humanoid(P, {
      limb: 1.1, bulk: 1.15, hips: .95, skin, skinFar, bareArms: true, gloves: true,
      top: R ? ['#6a0a0a', '#400606'] : ['#4a1010', '#2a0808'], topFar: ['#2a0808', '#1a0404'],
      pants: ['#2a2a2e', '#18181c'], pantsFar: ['#18181c', '#0e0e10'], boots: ['#141414', '#0a0a0a'], bootsFar: ['#0a0a0a', '#0a0a0a'],
      belt: ['#888888', '#555555'], glove: ['#3a2a2a', '#241a1a'], gloveFar: ['#241a1a', '#160f0f'],
    }, {
      back(P) { // torn crimson scarf streaming behind
        const a = [P.sh[0], P.sh[1] - 2], c = [P.sh[0] - 30, P.sh[1] + s.s1 * 8], e = [P.sh[0] - 60, P.sh[1] + 10 + s.s2 * 10], pts = [];
        for (let i = 0; i <= 6; i++) { const u = i / 6; pts.push([(1 - u) ** 2 * a[0] + 2 * u * (1 - u) * c[0] + u * u * e[0], (1 - u) ** 2 * a[1] + 2 * u * (1 - u) * c[1] + u * u * e[1]]); }
        g.paint(pts.slice(1).map((q, i) => g.cap(pts[i], q, 3.4 - i * .3)), '#8a0a0a', '#5a0606');
      },
      chest(P) { // open vest: bare, scarred chest
        const [x, y] = L(P.hip, P.sh, .55);
        g.paint([g.poly([[x - 6, y - 16], [x + 8, y - 16], [x + 5, y + 14], [x - 4, y + 14]])], ...skin, false);
        g.line([[x - 4, y - 10], [x + 6, y + 4]], '#6a2020', 1.3); g.line([[x + 6, y - 12], [x - 2, y]], '#6a2020', 1.3);
      },
      head(P) {
        const [hx, hy] = P.head, up = s.F ? 4 : 0, pts = [[hx - 8, hy - 8]];
        for (let i = 0; i < 6; i++) pts.push([hx - 8 + i * 3.5, hy - 16 - (i % 2) * 6 - up]);
        pts.push([hx + 12, hy - 8]);
        g.paint([g.poly(pts)], '#c01818', '#8a0a0a');
        g.fill(g.poly([[hx + 2, hy - 4], [hx + 12, hy - 5], [hx + 11, hy], [hx + 2, hy + 2]]), '#c01818');
        g.fill(g.poly([[hx + 5, hy - 3], [hx + 10, hy - 2.5], [hx + 9.5, hy - 1], [hx + 5, hy - 1.5]]), '#ffffff');
        g.fill(g.poly([[hx + 3, hy + 5], [hx + 11, hy + 4], [hx + 10, hy + 8], [hx + 4, hy + 8.5]]), '#1a0a0a');
        g.fill(g.poly([[hx + 4, hy + 5], [hx + 10.5, hy + 4.4], [hx + 10.2, hy + 6], [hx + 4.3, hy + 6.6]]), '#f0e8e0');
        g.line([[hx - 4, hy + 2], [hx - 1, hy + 7]], '#6a2020', 1.2);
      },
      pads(P) {
        g.paint([g.ell(P.sh[0], P.sh[1] + 2, 10, 10, 0, Math.PI, Math.PI * 2)], '#555555', '#3a3a3a');
        g.paint([-6, 0, 6].map(dx => g.poly([[P.sh[0] + dx - 2.4, P.sh[1] - 6], [P.sh[0] + dx, P.sh[1] - 17], [P.sh[0] + dx + 2.4, P.sh[1] - 6]])), '#aaaaaa', '#777777');
      },
      front(P) { // the serrated cleaver
        const m = new DOMMatrix().translate(P.fH[0], P.fH[1]).rotate(s.ang * 180 / Math.PI);
        g.paint([g.moved(g.poly([[-26, -3.5], [2, -3.5], [2, 3.5], [-26, 3.5]]), m)], '#2a1a1a', '#1a0f0f');
        g.paint([g.moved(g.poly([[0, -12], [7, -12], [7, 12], [0, 12]]), m)], '#555555', '#3a3a3a');
        g.paint([g.moved(g.poly([[7, 9], [118, 9], [118, 12], [7, 12]]), m), ...[0, 1, 2, 3, 4].map(i => g.moved(g.poly([[20 + i * 20, 9], [26 + i * 20, 15], [32 + i * 20, 9]]), m))], '#1a1a1a', '#0a0a0a');
        g.paint([g.moved(g.poly([[7, -9], [118, -8], [140, 0], [118, 9], [7, 9]]), m)], rage ? '#cc3333' : '#9aa0a8', rage ? '#8a1a1a' : '#6a7078');
        g.fill(g.moved(g.shape([['M', 80, -8], ['Q', 96, -2, 90, 8], ['L', 76, 8]]), m), '#8a0a0a');
        const pt = (x, y) => { const q = m.transformPoint(new DOMPoint(x, y)); return [q.x, q.y]; };
        g.line([pt(10, -7), pt(116, -6.5)], rage ? '#ff7070' : '#dfe4ea', 1.2);
      },
    });
  },
  pre(c, v, P, s) {
    const t = v.anim || 0, m = v.move;
    if (s.F || s.R) { c.save(); c.globalCompositeOperation = 'lighter'; glowCircle(c, 0, -70, 110 + (s.F ? Math.sin(t * 16) * 10 : 0), `rgba(255,20,20,${s.F ? 0.35 : 0.2})`, 'rgba(0,0,0,0)'); c.restore(); }
    if (m && m.rzTempest) { c.save(); c.globalCompositeOperation = 'lighter'; for (let i = 0; i < 3; i++) { c.strokeStyle = `rgba(255,${30 + i * 40},30,${0.6 - i * 0.15})`; c.lineWidth = 8 - i * 2; c.beginPath(); c.ellipse(0, -70 + i * 10, 110 - i * 14, 40, 0, t * 20 + i, t * 20 + i + 4.4); c.stroke(); } c.restore(); }
  },
  post(c, v, P, s) {
    c.save(); c.globalCompositeOperation = 'lighter';
    glowCircle(c, P.head[0] + 7, P.head[1] - 2, s.F || s.R ? 7 : 4, 'rgba(255,40,40,1)', 'rgba(0,0,0,0)');
    if (s.R || s.F || s.spin) { c.translate(P.fH[0], P.fH[1]); c.rotate(s.ang); c.strokeStyle = 'rgba(255,30,30,0.6)'; c.lineWidth = 6; c.beginPath(); c.moveTo(10, 0); c.lineTo(138, 0); c.stroke(); }
    c.restore();
  },
});

// ---------------- hook them into the roster ----------------
// Settings → PIXEL ART FIGHTERS switches every pixel fighter back to its vector art.
const pixelArtOn = () => !(typeof Save !== 'undefined' && Save.set && Save.set.pixelArt === false);
(() => {
  const set = (id, px, b64, formFx) => {
    const def = charById(id), oldDraw = def.draw, oldPortrait = def.drawPortrait;
    const pixPortrait = b64 ? PixelArt.portrait(id, b64, oldPortrait, formFx) : oldPortrait;
    def.draw = (c, v) => pixelArtOn() ? px.draw(c, v) : oldDraw(c, v);
    def.drawPortrait = (c, o, d) => pixelArtOn() ? pixPortrait(c, o, d) : oldPortrait(c, o, d);
  };
  // Aatrox's def already points at his pixel versions; give him his vector ones as the fallback.
  const aat = charById('aatrox');
  aat.draw = (c, v) => pixelArtOn() ? AATPX.draw(c, v) : drawAatrox(c, v);
  aat.drawPortrait = (c, o, d) => pixelArtOn() ? drawAatroxPixelPortrait(c, o, d) : drawAatroxPortraitVector(c, o);
  set('kael', KAELPX, '', PixelArt.formGlow('rgba(255,70,20,0.4)', 'rgba(255,110,40,0.85)'));
  set('seraph', SERPX, '', PixelArt.formGlow('rgba(255,245,210,0.35)', 'rgba(255,250,220,0.9)'));
  set('sion', SIONPX, '', PixelArt.formGlow('rgba(255,90,40,0.3)', 'rgba(255,140,70,0.85)'));
  set('razor', RAZORPX, '', PixelArt.formGlow('rgba(255,30,30,0.4)', 'rgba(255,80,80,0.85)'));
})();
